import os
from datetime import date
from typing import Annotated

from fastapi import APIRouter, Depends, FastAPI, Header, HTTPException, Query, Response
from pydantic import AwareDatetime, BaseModel, Field

from pulso import correo, db, reloj

router = APIRouter()


def socio_actual(authorization: str | None = Header(default=None)):
    if not authorization or not authorization.startswith('Bearer '):
        raise HTTPException(401, 'Falta el token')
    socio = db.socio_por_token(authorization.removeprefix('Bearer '))
    if socio is None:
        raise HTTPException(401, 'Token inválido')
    return socio


def admin(x_admin_key: str | None = Header(default=None)):
    if not x_admin_key or x_admin_key != os.environ.get('PULSO_ADMIN_KEY'):
        raise HTTPException(401, 'Clave de administración inválida')


def ver_clase(clase):
    return dict(clase, lugares_libres=clase['cupo'] - db.confirmadas(clase['id']))


def ver_reserva(reserva):
    return {k: reserva[k] for k in ('id', 'clase_id', 'estado', 'creada')}


FECHA = r'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'


def fecha_del_filtro(texto):
    if texto is None:
        return None
    try:
        return date.fromisoformat(texto)
    except ValueError:
        raise HTTPException(422, 'La fecha tiene que ser YYYY-MM-DD')


@router.get('/clases')
def listar_clases(
    response: Response,
    desde: Annotated[str | None, Query(pattern=FECHA)] = None,
    hasta: Annotated[str | None, Query(pattern=FECHA)] = None,
    instructor: str | None = None,
    con_lugar: bool = False,
    pagina: Annotated[int, Query(ge=1)] = 1,
    por_pagina: Annotated[int, Query(ge=1, le=50)] = 20,
):
    desde_dia, hasta_dia = fecha_del_filtro(desde), fecha_del_filtro(hasta)
    if desde_dia and hasta_dia and desde_dia > hasta_dia:
        raise HTTPException(422, 'desde no puede ser posterior a hasta')
    ahora = reloj.ahora()

    def cumple(clase):
        inicio = db.a_fecha(clase['inicio'])
        if inicio <= ahora:
            return False
        dia = inicio.astimezone(reloj.MONTEVIDEO).date()
        if desde_dia and dia < desde_dia:
            return False
        if hasta_dia and dia > hasta_dia:
            return False
        if instructor is not None and clase['instructor'].casefold() != instructor.casefold():
            return False
        if con_lugar and clase['lugares_libres'] <= 0:
            return False
        return True
